<?php require __DIR__.'/_init.php';require_login();$s=db()->prepare('SELECT * FROM service_requests WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();page_start('My requests');?><div class="row"><div><div class="eyebrow">YOUR SUPPORT HISTORY</div><h1>My requests</h1></div><a class="button" href="/new-request.php">New request +</a></div><?php if(!$rows):?><div class="empty"><p>No requests yet.</p><a href="/new-request.php">Create your first request →</a></div><?php else:?><div class="table-wrap"><table><tr><th>Tracking ID</th><th>Request</th><th>Category</th><th>Status</th><th>Expected response</th><th>Submitted</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['tracking_id'])?></td><td><a href="/request.php?id=<?=e($r['id'])?>"><?=e($r['title'])?></a></td><td><?=e($r['category'])?></td><td><span class="pill"><?=e(str_replace('_',' ',$r['status']))?></span></td><td>About <?=e($r['expected_days'])?> days</td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?><?php page_end();?>
